gabP(){return"\u0646\u0648\u0639 \u0627\u0644\u062d\u0627\u0644\u0629"},
gabM(){return"\u0627\u0644\u0645\u0627\u062f\u0629 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a\u0629"},
gabL(){return"\u0625\u0636\u0627\u0641\u0629 \u0646\u0648\u0639"},
